CREATE TABLE workspaces (id TEXT PRIMARY KEY NOT NULL, created_at TEXT NOT NULL, label TEXT);
CREATE TABLE devices (device_id TEXT PRIMARY KEY NOT NULL, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, app_version TEXT);
CREATE TABLE workspace_devices (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES devices(device_id) ON DELETE CASCADE, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, label TEXT, PRIMARY KEY(workspace_id,device_id));
CREATE TABLE access_tokens (id TEXT PRIMARY KEY NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('ingest','agent_read')), token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, last_used_at TEXT, revoked_at TEXT);
CREATE INDEX access_tokens_workspace ON access_tokens(workspace_id);
CREATE TABLE sync_batches (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, export_id TEXT NOT NULL, device_id TEXT NOT NULL REFERENCES devices(device_id) ON DELETE CASCADE, generated_at TEXT NOT NULL, received_at TEXT NOT NULL, schema_version INTEGER NOT NULL, timezone TEXT NOT NULL, source TEXT NOT NULL, date_range_start TEXT NOT NULL, date_range_end TEXT NOT NULL CHECK(date_range_end >= date_range_start), metrics_count INTEGER NOT NULL CHECK(metrics_count >= 0), workouts_count INTEGER NOT NULL CHECK(workouts_count >= 0), PRIMARY KEY(workspace_id,export_id));
CREATE TABLE health_metrics (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES devices(device_id) ON DELETE CASCADE, id TEXT NOT NULL, type TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL CHECK(end_at >= start_at), source_name TEXT NOT NULL, source_bundle_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', export_id TEXT NOT NULL, PRIMARY KEY(workspace_id,device_id,id), FOREIGN KEY(workspace_id,export_id) REFERENCES sync_batches(workspace_id,export_id) ON DELETE CASCADE);
CREATE TABLE health_workouts (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES devices(device_id) ON DELETE CASCADE, id TEXT NOT NULL, activity_type TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL CHECK(end_at >= start_at), duration_seconds REAL NOT NULL CHECK(duration_seconds >= 0), total_energy_kcal REAL CHECK(total_energy_kcal IS NULL OR total_energy_kcal >= 0), active_energy_kcal REAL CHECK(active_energy_kcal IS NULL OR active_energy_kcal >= 0), distance_meters REAL CHECK(distance_meters IS NULL OR distance_meters >= 0), source_name TEXT NOT NULL, source_bundle_id TEXT, metadata TEXT NOT NULL DEFAULT '{}', export_id TEXT NOT NULL, PRIMARY KEY(workspace_id,device_id,id), FOREIGN KEY(workspace_id,export_id) REFERENCES sync_batches(workspace_id,export_id) ON DELETE CASCADE);
CREATE INDEX sync_batches_workspace_received ON sync_batches(workspace_id,received_at DESC,export_id);
CREATE INDEX sync_batches_device_received ON sync_batches(device_id,received_at);
CREATE INDEX metrics_workspace_start ON health_metrics(workspace_id,start_at DESC,device_id,id);
CREATE INDEX metrics_workspace_type_start ON health_metrics(workspace_id,type,start_at DESC,device_id,id);
CREATE INDEX metrics_export ON health_metrics(workspace_id,export_id);
CREATE INDEX workouts_workspace_start ON health_workouts(workspace_id,start_at DESC,device_id,id);
CREATE INDEX workouts_workspace_activity_start ON health_workouts(workspace_id,activity_type,start_at DESC,device_id,id);
CREATE INDEX workouts_export ON health_workouts(workspace_id,export_id);
